// rr_arbiter: round-robin arbiter for N requesters.
// Implements microarchitecture.md for interface_spec.md (task prj-5041006167).
// State: one priority pointer ptr. grant is combinational from req and ptr.
// The winner is the first requester with req high at or after ptr, searching
// upwards and wrapping from N-1 to 0. On a rising edge with a grant, ptr
// moves to one past the winner. rst_n is synchronous, active low.
module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);

    localparam integer PW     = (N > 1) ? $clog2(N) : 1;
    localparam [N-1:0] ONE_N  = {{(N-1){1'b0}}, 1'b1};
    localparam [N-1:0] ZERO_N = {N{1'b0}};

    reg  [PW-1:0] ptr;
    reg  [PW-1:0] ptr_next;
    wire [N-1:0]  ptr_oh = ONE_N << ptr;

    // Grant: walk N candidates from ptr upwards. The candidate is one-hot and
    // rotates by one bit per step; bit N-1 wraps explicitly into bit 0.
    reg  [N-1:0]  cand;
    reg           found;
    integer       k;

    always @* begin
        grant = ZERO_N;
        found = 1'b0;
        cand  = ptr_oh;
        for (k = 0; k < N; k = k + 1) begin
            if (!found && ((req & cand) != ZERO_N)) begin
                grant = cand;
                found = 1'b1;
            end
            cand = {cand[N-2:0], cand[N-1]};
        end
    end

    // Next pointer: one past the winner, with winner N-1 going to 0.
    // Encoded directly from the one-hot grant.
    integer w;
    integer b;

    always @* begin
        ptr_next = {PW{1'b0}};
        for (w = 0; w < N; w = w + 1) begin
            for (b = 0; b < PW; b = b + 1) begin
                if (((((w == N - 1) ? 0 : (w + 1)) >> b) & 1) == 1) begin
                    ptr_next[b] = ptr_next[b] | grant[w];
                end
            end
        end
    end

    // Pointer register: reset to 0; move only on a cycle with a grant.
    always @(posedge clk) begin
        if (!rst_n) begin
            ptr <= {PW{1'b0}};
        end else if (grant != ZERO_N) begin
            ptr <= ptr_next;
        end
    end

`ifdef FORMAL
    // Design-intent properties (not run in this task).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume (!rst_n);
    end

    reg [PW-1:0] f_win;
    integer      fi;
    always @(*) begin
        f_win = {PW{1'b0}};
        for (fi = 0; fi < N; fi = fi + 1) begin
            if (grant[fi]) f_win = fi;
        end
    end

    wire [PW:0] f_win_dist = (f_win >= ptr) ? (f_win - ptr) : (f_win + N - ptr);

    always @(*) begin
        if (f_past_valid) begin
            assert (ptr < N);
            assert ((grant & (grant - ONE_N)) == ZERO_N);
            assert ((grant & ~req) == ZERO_N);
            if (req != ZERO_N) assert (grant != ZERO_N);
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert (ptr == 0);
            end else if ($past(grant) != ZERO_N) begin
                assert (ptr == (($past(f_win) == N - 1) ? 0 : ($past(f_win) + 1)));
            end else begin
                assert (ptr == $past(ptr));
            end
        end
    end

    always @(posedge clk) begin
        if (f_past_valid && rst_n) begin
            cover (req == {N{1'b1}});
            cover ($past(rst_n) && ($past(ptr) == N - 1) && (ptr == 0));
        end
    end

    genvar fg;
    generate
        for (fg = 0; fg < N; fg = fg + 1) begin : g_formal
            wire [PW:0] f_dist = (fg >= ptr) ? (fg - ptr) : (fg + N - ptr);
            reg  [PW:0] f_wait;
            initial f_wait = {(PW+1){1'b0}};
            always @(posedge clk) begin
                if (!rst_n) f_wait <= {(PW+1){1'b0}};
                else if (req[fg] && !grant[fg]) f_wait <= f_wait + 1'b1;
                else f_wait <= {(PW+1){1'b0}};
            end
            always @(*) begin
                if (f_past_valid) begin
                    // Round-robin order: no requester between ptr and the winner.
                    if (req[fg] && !grant[fg]) assert (f_win_dist < f_dist);
                    // Starvation bound with its induction invariant.
                    assert (f_wait + f_dist <= N - 1);
                    assert (f_wait <= N - 1);
                end
            end
            always @(posedge clk) begin
                if (f_past_valid && rst_n) begin
                    cover (grant[fg]);
                    cover (f_wait == N - 1);
                end
            end
        end
    endgenerate
`endif

endmodule
=== END FILE ===
