// rr_arbiter_tb: self-checking testbench for rr_arbiter (task prj-5041006167).
// Two arbiters run side by side, N = 4 and N = 5. Each is checked every rising
// edge against a reference pointer model and per-requester wait counters.
// Coverage goals fail the run if not reached.

module rr_arbiter_tb;
    reg clk = 1'b0;
    always #5 clk = ~clk;

    wire done4;
    wire done5;

    rr_arbiter_check #(.N(4)) u_n4 (.clk(clk), .done(done4));
    rr_arbiter_check #(.N(5)) u_n5 (.clk(clk), .done(done5));

    reg [8*64-1:0] nonce;
    integer        passed;
    integer        failed;
    integer        t_passed;
    integer        t_failed;
    reg            ended = 1'b0;

    initial begin
        nonce = {64{8'h00}};
        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) begin
            nonce = {64{8'h00}};
        end
        wait (done4 && done5);
        repeat (2) @(negedge clk);
        passed = u_n4.passed + u_n4.cov_passed + u_n5.passed + u_n5.cov_passed;
        failed = u_n4.failed + u_n4.cov_failed + u_n5.failed + u_n5.cov_failed;
        ended  = 1'b1;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    initial begin
        #1000000;
        if (!ended) begin
            t_passed = u_n4.passed + u_n4.cov_passed + u_n5.passed + u_n5.cov_passed;
            t_failed = u_n4.failed + u_n4.cov_failed + u_n5.failed + u_n5.cov_failed + 1;
            $error("rr_arbiter_tb: timeout before both checkers finished");
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, t_passed, t_failed);
            $finish;
        end
    end
endmodule

module rr_arbiter_check #(
    parameter integer N = 4
) (
    input  wire clk,
    output reg  done
);
    localparam [N-1:0] ALL_N  = {N{1'b1}};
    localparam [N-1:0] ZERO_N = {N{1'b0}};
    localparam [N-1:0] ONE_N  = {{(N-1){1'b0}}, 1'b1};

    reg          rst_n;
    reg  [N-1:0] req;
    wire [N-1:0] grant;

    rr_arbiter #(.N(N)) u_dut (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req),
        .grant (grant)
    );

    // Check counters (read by the top for the verdict).
    integer passed     = 0;
    integer failed     = 0;
    integer cov_passed = 0;
    integer cov_failed = 0;

    // Reference model and fairness state.
    integer     cyc       = 0;
    integer     model_ptr = 0;
    integer     wait_cnt [0:N-1];
    integer     max_wait  = 0;
    reg [N-1:0] prev_req   = {N{1'b0}};
    reg         prev_rst_n = 1'b0;
    reg         released   = 1'b0;

    // Coverage counters.
    integer     cov_none        = 0;
    integer     cov_all         = 0;
    integer     cov_contend     = 0;
    integer     cov_wrap        = 0;
    integer     cov_held        = 0;
    integer     cov_rst_traffic = 0;
    integer     cov_maxwait     = 0;
    reg [N-1:0] seen_alone      = {N{1'b0}};

    reg [N-1:0] exp_grant;
    reg         exp_found;
    integer     exp_idx;
    integer     idx;
    integer     k;
    integer     i;
    reg [N-1:0] alone;

    always @(posedge clk) begin
        cyc = cyc + 1;

        // Expected grant: first requester at or after the model pointer, wrapping at N.
        exp_grant = ZERO_N;
        exp_found = 1'b0;
        exp_idx   = 0;
        for (k = 0; k < N; k = k + 1) begin
            idx = model_ptr + k;
            if (idx >= N) idx = idx - N;
            if (!exp_found && req[idx]) begin
                exp_found = 1'b1;
                exp_idx   = idx;
            end
        end
        if (exp_found) exp_grant[exp_idx] = 1'b1;

        if (grant === exp_grant) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $error("rr_arbiter N=%0d cycle %0d: grant %b, expected %b (req %b, rst_n %b, model ptr %0d)",
                   N, cyc, grant, exp_grant, req, rst_n, model_ptr);
        end

        // Fairness: a held request waits at most N-1 cycles.
        for (i = 0; i < N; i = i + 1) begin
            if (!rst_n) wait_cnt[i] = 0;
            else if (req[i] && !grant[i]) wait_cnt[i] = wait_cnt[i] + 1;
            else wait_cnt[i] = 0;
            if (wait_cnt[i] <= N - 1) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("rr_arbiter N=%0d cycle %0d: requester %0d waited %0d cycles, bound is %0d",
                       N, cyc, i, wait_cnt[i], N - 1);
            end
            if (wait_cnt[i] > max_wait) max_wait = wait_cnt[i];
            if (wait_cnt[i] == N - 1) cov_maxwait = cov_maxwait + 1;
        end

        // Coverage.
        if (rst_n) begin
            released = 1'b1;
            if (req == ZERO_N) cov_none = cov_none + 1;
            if (req == ALL_N) cov_all = cov_all + 1;
            if ((req & (req - ONE_N)) != ZERO_N) begin
                cov_contend = cov_contend + 1;
                if (exp_found && (exp_idx == N - 1)) cov_wrap = cov_wrap + 1;
            end
            for (i = 0; i < N; i = i + 1) begin
                alone = ZERO_N;
                alone[i] = 1'b1;
                if (req == alone) seen_alone[i] = 1'b1;
            end
            if (prev_rst_n && req[1] && prev_req[1] && (req != prev_req)) cov_held = cov_held + 1;
        end else if (released && (req != ZERO_N)) begin
            cov_rst_traffic = cov_rst_traffic + 1;
        end

        // Model pointer update.
        if (!rst_n) model_ptr = 0;
        else if (exp_found) model_ptr = (exp_idx == N - 1) ? 0 : (exp_idx + 1);

        prev_req   = req;
        prev_rst_n = rst_n;
    end

    task step;
        input [N-1:0] r;
        input         rs;
        begin
            @(negedge clk);
            req   = r;
            rst_n = rs;
        end
    endtask

    initial begin : stim
        integer     j;
        integer     s;
        reg [31:0]  rnd;
        reg [N-1:0] rv;

        done  = 1'b0;
        req   = ZERO_N;
        rst_n = 1'b0;

        // Reset with no traffic.
        step(ZERO_N, 1'b0);
        step(ZERO_N, 1'b0);

        // No requests.
        for (j = 0; j < 3; j = j + 1) step(ZERO_N, 1'b1);

        // Each requester alone.
        for (s = 0; s < N; s = s + 1) begin
            rv = ZERO_N;
            rv[s] = 1'b1;
            step(rv, 1'b1);
            step(rv, 1'b1);
        end

        // Everyone requesting: strict rotation and the longest fair wait (N-1).
        for (j = 0; j < 3 * N; j = j + 1) step(ALL_N, 1'b1);

        // A held request (requester 1) among changing others.
        for (j = 0; j < 8 * N; j = j + 1) begin
            rnd = $random;
            rv = rnd[N-1:0];
            rv[1] = 1'b1;
            step(rv, 1'b1);
        end

        // Random subsets under contention.
        for (j = 0; j < 400; j = j + 1) begin
            rnd = $random;
            step(rnd[N-1:0], 1'b1);
        end

        // Sparse requests, dropped and raised again.
        for (j = 0; j < 200; j = j + 1) begin
            rnd = $random;
            rv = rnd[N-1:0] & rnd[N+7:8];
            step(rv, 1'b1);
        end

        // Reset during traffic.
        for (j = 0; j < 3; j = j + 1) step(ALL_N, 1'b1);
        rnd = $random;
        step(rnd[N-1:0] | ONE_N, 1'b0);
        rnd = $random;
        step(rnd[N-1:0] | ONE_N, 1'b0);
        for (j = 0; j < 2 * N; j = j + 1) step(ALL_N, 1'b1);

        // Quiet tail.
        for (j = 0; j < 3; j = j + 1) step(ZERO_N, 1'b1);
        @(negedge clk);

        // Coverage goals.
        if (cov_none > 0) cov_passed = cov_passed + 1;
        else begin cov_failed = cov_failed + 1; $error("rr_arbiter N=%0d: coverage not reached: no requests", N); end
        if (seen_alone == ALL_N) cov_passed = cov_passed + 1;
        else begin cov_failed = cov_failed + 1; $error("rr_arbiter N=%0d: coverage not reached: each requester alone (%b)", N, seen_alone); end
        if (cov_all > 0) cov_passed = cov_passed + 1;
        else begin cov_failed = cov_failed + 1; $error("rr_arbiter N=%0d: coverage not reached: everyone requesting", N); end
        if (cov_contend > 0) cov_passed = cov_passed + 1;
        else begin cov_failed = cov_failed + 1; $error("rr_arbiter N=%0d: coverage not reached: contention", N); end
        if (cov_wrap > 0) cov_passed = cov_passed + 1;
        else begin cov_failed = cov_failed + 1; $error("rr_arbiter N=%0d: coverage not reached: pointer wrap from N-1", N); end
        if (cov_held > 0) cov_passed = cov_passed + 1;
        else begin cov_failed = cov_failed + 1; $error("rr_arbiter N=%0d: coverage not reached: held request among changing others", N); end
        if (cov_maxwait > 0) cov_passed = cov_passed + 1;
        else begin cov_failed = cov_failed + 1; $error("rr_arbiter N=%0d: coverage not reached: longest fair wait N-1 (max seen %0d)", N, max_wait); end
        if (cov_rst_traffic > 0) cov_passed = cov_passed + 1;
        else begin cov_failed = cov_failed + 1; $error("rr_arbiter N=%0d: coverage not reached: reset during traffic", N); end

        done = 1'b1;
    end
endmodule
=== END FILE ===
